\label{lemma-check-torsion-on-affines}
Let $X$ be an integral scheme. Let $\mathcal{F}$ be a quasi-coherent
$\mathcal{O}_X$-module. The following are equivalent
\begin{enumerate}
\item $\mathcal{F}$ is torsion free,
\item for $U \subset X$ affine open $\mathcal{F}(U)$
is a torsion free $\mathcal{O}(U)$-module.
\end{enumerate}

\label{lemma-flat-torsion-free}
Let $X$ be an integral scheme. Any flat quasi-coherent $\mathcal{O}_X$-module
is torsion free.

\label{lemma-flat-over-integral-integral-fibre}
Let $f : X \to Y$ be a flat morphism of schemes. If $Y$ is integral
and the generic fibre of $f$ is integral, then $X$ is integral.

\label{lemma-torsion-free-over-regular-dim-1}
Let $X$ be an integral regular scheme of dimension $\leq 1$.
Let $\mathcal{F}$ be a coherent $\mathcal{O}_X$-module.
The following are equivalent
\begin{enumerate}
\item $\mathcal{F}$ is torsion free,
\item $\mathcal{F}$ is finite locally free.
\end{enumerate}

\label{lemma-check-rank-on-affines}
Let $X$ be an integral scheme. Let $\mathcal{F}$ be a quasi-coherent
$\mathcal{O}_X$-module. Let $r$ be a cardinal. The following are equivalent
\begin{enumerate}
\item $\mathcal{F}$ has rank $r$,
\item for all $U \subset X$ nonempty affine open $\mathcal{F}(U)$
is an $\mathcal{O}_X(U)$-module of rank $r$, and
\item for some $U \subset X$ nonempty affine open $\mathcal{F}(U)$
is an $\mathcal{O}_X(U)$-module of rank $r$.
\end{enumerate}

\label{lemma-finite-module-rank}
Let $X$ be an integral scheme. Let $\mathcal{F}$ be a finite type
quasi-coherent $\mathcal{O}_X$-module. Then
\begin{enumerate}
\item $\mathcal{F}$ has finite rank $r \geq 0$, and
\item there exists a nonempty open $U \subset X$
such that $\mathcal{F}|_U$ is free of rank $r$.
\end{enumerate}

conclusions:
\begin{enumerate}
\item $\mathcal{F}$ has finite rank $r \geq 0$, and
\item there exists a nonempty open $U \subset X$
such that $\mathcal{F}|_U$ is free of rank $r$.
\end{enumerate}

